// Solid sets unknown SVG props as attributes, accepts `class`, and renders
// `innerHTML` as children during SSR and hydration.
module.exports = ({
  attributes,
  markup,
  origin,
}) => `/** @jsxImportSource @solidjs/web */
// Generated by UltraModern from ${origin}. Do not edit.
import type { JSX } from '@solidjs/web';

const attributes: { readonly [name: string]: string } = ${attributes};
const markup = ${markup};

export default function SvgComponent(
  props: { readonly [name: string]: unknown },
): JSX.Element {
  return <svg {...attributes} {...props} innerHTML={markup} />;
}
`;
